const Database = require\(''better-sqlite3''\);
const path = require\(''path''\);
const os = require\(''os''\);

const dbPath = path.join\(os.homedir\(\), ''AppData'', ''Roaming'', ''CanvasAssistant'', ''canvas.db''\);
const db = new Database\(dbPath, { readonly: true }\);

// Find ECE311 course
const course = db.prepare\(""SELECT id, name, code FROM courses WHERE name LIKE ''%ECE311%'' OR code LIKE ''%ECE311%''""\).get\(\);
console.log\(''Course:'', JSON.stringify\(course, null, 2\)\);

if \(course\) {
  // Find HW1 task
  const task = db.prepare\(""SELECT id, external_id, title, is_completed, completed_at, submission_status, grade, source_type FROM tasks WHERE course_id = ? AND title LIKE ''%HW1%'' OR title LIKE ''%Homework 1%''""\).all\(course.id\);
  console.log\(''\\nTasks matching HW1:'', JSON.stringify\(task, null, 2\)\);
}

db.close\(\);
")
